INSERT INTO interview_open_questions (id, area_id, position, prompt, good_answer) VALUES
('cf-aberta-01', 'corporate-finance', 1, 'O que faz a área de finanças corporativas de uma empresa? Como ela se diferencia de um banco de investimento?', 'Decisões de investimento, financiamento e caixa, vividas de dentro da empresa; o banco assessora de fora'),
('cf-aberta-02', 'corporate-finance', 2, 'Uma empresa com lucro pode quebrar? Como?', 'Lucro não é caixa: vender a prazo, estoque alto e dívida curta podem secar o caixa'),
('cf-aberta-03', 'corporate-finance', 3, 'Como as três demonstrações financeiras se conectam?', 'O lucro da DRE entra no patrimônio do balanço e começa o fluxo de caixa; o caixa final do fluxo aparece no balanço'),
('cf-aberta-04', 'corporate-finance', 4, 'Se a depreciação aumenta R$ 10, o que acontece nas três demonstrações (imposto de 34%)?', 'Lucro cai R$ 6,60; caixa sobe R$ 3,40 pela economia de imposto; ativo cai R$ 6,60 e patrimônio também'),
('cf-aberta-05', 'corporate-finance', 5, 'O que é capital de giro e por que ele consome caixa quando a empresa cresce?', 'Mais vendas exigem mais estoque e mais contas a receber antes de o dinheiro entrar'),
('cf-aberta-06', 'corporate-finance', 6, 'O que é ciclo de caixa? Cite duas formas de reduzi-lo.', 'Recebimento + estoque − pagamento; negociar prazos, reduzir estoque, antecipar recebíveis'),
('cf-aberta-07', 'corporate-finance', 7, 'O que é EBITDA e quais são as limitações dele?', 'Aproxima a geração de caixa operacional, mas ignora investimento, capital de giro, juros e impostos'),
('cf-aberta-08', 'corporate-finance', 8, 'Qual a diferença entre VPL e TIR? Quando elas podem dar sinais diferentes?', 'VPL em reais e TIR em taxa; projetos de tamanhos ou prazos diferentes podem ordenar diferente; o VPL decide'),
('cf-aberta-09', 'corporate-finance', 9, 'Por que o payback, sozinho, é um critério fraco?', 'Ignora o valor do dinheiro no tempo e o que acontece depois do prazo'),
('cf-aberta-10', 'corporate-finance', 10, 'O que é WACC e por que ele é usado como taxa de desconto?', 'Custo médio de dívida e capital próprio; é o retorno mínimo que o projeto precisa entregar'),
('cf-aberta-11', 'corporate-finance', 11, 'Por que o capital dos sócios costuma ser mais caro que a dívida?', 'Sócio recebe por último e corre mais risco; juros da dívida reduzem imposto'),
('cf-aberta-12', 'corporate-finance', 12, 'O que é alavancagem (dívida líquida / EBITDA) e por que os bancos olham para ela?', 'Quantos anos de geração de caixa pagam a dívida; mede a capacidade de pagar'),
('cf-aberta-13', 'corporate-finance', 13, 'O que é um covenant e o que acontece se ele for quebrado?', 'Limite contratual; a quebra pode antecipar o vencimento da dívida ou exigir renegociação'),
('cf-aberta-14', 'corporate-finance', 14, 'Como você decide entre financiar um investimento com dívida ou com caixa próprio?', 'Custo, prazo, flexibilidade, alavancagem e o efeito de ambos na dívida líquida'),
('cf-aberta-15', 'corporate-finance', 15, 'O que é FP&A? Como funciona um ciclo de orçamento e forecast?', 'Plano anual, acompanhamento mensal, revisões periódicas e análise de variações'),
('cf-aberta-16', 'corporate-finance', 16, 'A receita veio 10% abaixo do orçado. Como você investigaria?', 'Separar efeito preço, volume e mix; olhar por produto, região e cliente; ouvir a área comercial'),
('cf-aberta-17', 'corporate-finance', 17, 'O que é hedge cambial? Quando uma empresa deveria fazer?', 'Proteção contra o dólar para quem tem receita, custo ou dívida em moeda estrangeira'),
('cf-aberta-18', 'corporate-finance', 18, 'Como a alta da Selic afeta uma empresa endividada e outra com muito caixa?', 'A endividada paga mais juros (se a dívida é pós-fixada); a com caixa rende mais'),
('cf-aberta-19', 'corporate-finance', 19, 'Qual a diferença entre custo fixo e variável? O que é alavancagem operacional?', 'Custos fixos ampliam o efeito das vendas no lucro, para cima e para baixo'),
('cf-aberta-20', 'corporate-finance', 20, 'O que é ponto de equilíbrio?', 'O volume de vendas em que a margem de contribuição paga os custos fixos'),
('cf-aberta-21', 'corporate-finance', 21, 'Como você montaria um business case para um novo projeto?', 'Premissas claras, fluxo de caixa, VPL e TIR, sensibilidades, riscos e recomendação'),
('cf-aberta-22', 'corporate-finance', 22, 'A empresa tem caixa sobrando. O que fazer com ele?', 'Comparar investir, pagar dívida, distribuir dividendos ou recomprar ações, pelo retorno e pelo risco'),
('cf-aberta-23', 'corporate-finance', 23, 'Qual a diferença entre CAPEX e OPEX? Dê um exemplo de cada.', 'Investimento que gera benefício por anos (máquina) e despesa do dia a dia (energia)'),
('cf-aberta-24', 'corporate-finance', 24, 'Conte uma situação em que você usou dados para tomar ou mudar uma decisão.', 'Estrutura (situação, ação, resultado), números concretos e aprendizado'),
('cf-aberta-25', 'corporate-finance', 25, 'Por que finanças corporativas, e não banco ou mercado?', 'Motivação real: gosto por entender o negócio por dentro e ver o impacto das decisões'),
('st-aberta-01', 'sales-trading', 1, 'Qual a diferença entre sales e trading numa mesa?', 'Sales cuida do cliente e da ideia; trading dá o preço, executa e administra o risco'),
('st-aberta-02', 'sales-trading', 2, 'O que são bid, ask e spread? O que faz o spread aumentar?', 'Preço de compra, de venda e a diferença; spread sobe com menos liquidez e mais volatilidade'),
('st-aberta-03', 'sales-trading', 3, 'O que é market making e como a mesa ganha dinheiro com ele?', 'Oferecer compra e venda ao mesmo tempo e ganhar no spread, administrando o estoque de risco'),
('st-aberta-04', 'sales-trading', 4, 'O Copom surpreende e sobe os juros mais que o esperado. O que acontece com a curva de DI?', 'As taxas sobem, principalmente as curtas; os prefixados perdem valor'),
('st-aberta-05', 'sales-trading', 5, 'Qual a relação entre preço e taxa de um título prefixado? Por quê?', 'Inversa: se a taxa de mercado sobe, o fluxo fixo vale menos hoje'),
('st-aberta-06', 'sales-trading', 6, 'O que é DI futuro e para que ele serve?', 'Contrato da B3 sobre a taxa média de juros até uma data; serve para hedge e para posicionamento'),
('st-aberta-07', 'sales-trading', 7, 'O que significa estar "tomado" ou "dado" em taxa?', 'Tomado ganha com alta de juros; dado ganha com queda'),
('st-aberta-08', 'sales-trading', 8, 'O que é duration? E DV01?', 'Sensibilidade do preço aos juros; DV01 é o ganho ou perda para cada 0,01 ponto de mudança na taxa'),
('st-aberta-09', 'sales-trading', 9, 'O dólar sobe 10%. Quem ganha e quem perde entre uma exportadora e uma importadora? Como cada uma se protege?', 'Exportadora ganha, importadora perde; hedge com dólar futuro ou NDF'),
('st-aberta-10', 'sales-trading', 10, 'O que é um NDF e para quem ele é útil?', 'Contrato de câmbio a termo liquidado pela diferença; útil para empresas que querem travar o dólar'),
('st-aberta-11', 'sales-trading', 11, 'O que é liquidez e por que ela importa para o trader?', 'Define o custo e a velocidade para entrar e sair de uma posição'),
('st-aberta-12', 'sales-trading', 12, 'O que é stop loss? Por que respeitá-lo mesmo quando você acha que o mercado vai voltar?', 'Limita perdas e protege o capital; disciplina vale mais que convicção'),
('st-aberta-13', 'sales-trading', 13, 'Explique VaR em palavras simples.', 'A perda máxima esperada num período com certa confiança, por exemplo 95%'),
('st-aberta-14', 'sales-trading', 14, 'Me apresente uma ideia de operação em dois minutos.', 'Tese clara, por que agora, como executar, quanto pode ganhar e onde sair se der errado'),
('st-aberta-15', 'sales-trading', 15, 'Qual notícia de mercado da semana chamou sua atenção? O que você faria com ela?', 'Acompanha o mercado e liga notícia a preço e a decisão'),
('st-aberta-16', 'sales-trading', 16, 'Um cliente quer comprar R$ 50 milhões de um título pouco líquido. Como você executa?', 'Fatiar a ordem, buscar contrapartes, comunicar o cliente sobre preço e prazo, evitar mexer o mercado'),
('st-aberta-17', 'sales-trading', 17, 'O que é front-running e por que é proibido?', 'Operar antes da ordem de um cliente usando essa informação; é conduta ilegal e quebra a confiança'),
('st-aberta-18', 'sales-trading', 18, 'Você percebe que registrou uma operação errada e o mercado andou contra. O que faz?', 'Avisa na hora, corrige com o middle office e o gestor, registra o incidente; não esconde'),
('st-aberta-19', 'sales-trading', 19, 'Como o payroll americano pode afetar o real?', 'Emprego forte pode subir os juros americanos e fortalecer o dólar, pressionando o real'),
('st-aberta-20', 'sales-trading', 20, 'O que significa uma curva de juros inclinada? E invertida?', 'Inclinada: taxas longas maiores (expectativa de juros subindo ou mais risco); invertida: o mercado espera cortes'),
('st-aberta-21', 'sales-trading', 21, 'Explique a diferença entre uma opção de compra e uma de venda.', 'Call dá direito de comprar; put dá direito de vender, a um preço combinado'),
('st-aberta-22', 'sales-trading', 22, 'Conta rápida: quanto é 5% de 380? E 17 × 23?', 'Agilidade mental: 19 e 391'),
('st-aberta-23', 'sales-trading', 23, 'Conte uma situação em que você decidiu rápido sob pressão.', 'Exemplo real, critério usado e o que aprendeu'),
('st-aberta-24', 'sales-trading', 24, 'Por que Sales & Trading, e não research ou Investment Banking?', 'Gosto por ritmo, mercado ao vivo, decisões rápidas e contato com cliente'),
('st-aberta-25', 'sales-trading', 25, 'Se você tivesse R$ 10 mil hoje, onde investiria e por quê?', 'Raciocínio de risco e retorno, horizonte e liquidez, sem "dica quente"'),
('op-aberta-01', 'operacoes', 1, 'O que faz a área de operações e por que ela é crítica para uma instituição financeira?', 'Transforma decisões em operações reais e seguras; erros viram prejuízo e risco de reputação'),
('op-aberta-02', 'operacoes', 2, 'Qual a diferença entre front, middle e back office?', 'Quem negocia, quem confere e controla, e quem registra e liquida'),
('op-aberta-03', 'operacoes', 3, 'O que é liquidação? O que significam D+0, D+1 e D+2?', 'Troca do ativo pelo dinheiro e o número de dias úteis depois da negociação'),
('op-aberta-04', 'operacoes', 4, 'O que é custódia e qual o papel de uma central depositária, como a da B3?', 'Guarda dos ativos em nome do dono e registro oficial de quem possui o quê'),
('op-aberta-05', 'operacoes', 5, 'O que é conciliação? Dê um exemplo prático.', 'Comparar fontes (sistema, custódia, banco) e explicar cada diferença'),
('op-aberta-06', 'operacoes', 6, 'O sistema mostra 10.000 ações e a custódia, 9.500. Qual o seu passo a passo?', 'Investigar movimentações e eventos, achar a causa, confirmar e só então ajustar e registrar'),
('op-aberta-07', 'operacoes', 7, 'O que é a cota de um fundo e como ela é calculada?', 'Patrimônio líquido dividido pelo número de cotas, atualizado todo dia'),
('op-aberta-08', 'operacoes', 8, 'O que acontece com a posição e com o preço num desdobramento? E num grupamento?', 'Desdobramento multiplica as ações e divide o preço; grupamento faz o contrário; o valor total não muda'),
('op-aberta-09', 'operacoes', 9, 'O que são dividendos e juros sobre capital próprio? O que significam as datas "com" e "ex"?', 'Formas de distribuir lucro; quem tem a ação na data "com" recebe; na "ex", o preço já não inclui o direito'),
('op-aberta-10', 'operacoes', 10, 'O que é risco operacional? Dê três exemplos.', 'Falha de processo, de sistema ou de pessoa, como erro de digitação, sistema fora do ar e fraude'),
('op-aberta-11', 'operacoes', 11, 'O que é PLD e KYC? Por que operações participa disso?', 'Prevenção à lavagem e cadastro do cliente; operações vê movimentações e pode identificar algo estranho'),
('op-aberta-12', 'operacoes', 12, 'O que precisa ter numa boleta?', 'Ativo, quantidade, preço, cliente ou fundo, contraparte, datas de negociação e liquidação'),
('op-aberta-13', 'operacoes', 13, 'Uma liquidação falhou no fim do dia. O que você faz e quem avisa?', 'Entender a causa, avisar o gestor e a contraparte, seguir o procedimento e registrar'),
('op-aberta-14', 'operacoes', 14, 'Você tem cinco pendências e 30 minutos até o horário-limite. Como prioriza?', 'Pelo impacto financeiro e pelo prazo; o que tira dinheiro errado hoje vem primeiro'),
('op-aberta-15', 'operacoes', 15, 'Que tarefa manual você automatizaria primeiro e como?', 'Uma rotina repetitiva e com risco de erro, com Excel, SQL, Python ou ferramentas de automação'),
('op-aberta-16', 'operacoes', 16, 'O que é marcação a mercado?', 'Atualizar o valor dos ativos pelo preço de mercado, todos os dias'),
('op-aberta-17', 'operacoes', 17, 'Como a taxa de administração entra no cálculo da cota?', 'É provisionada diariamente e reduz o patrimônio todos os dias'),
('op-aberta-18', 'operacoes', 18, 'O que é segregação de funções e por que ela importa?', 'Quem negocia não liquida nem confere; reduz erro e fraude'),
('op-aberta-19', 'operacoes', 19, 'Um cliente pede por e-mail, com urgência, para trocar a conta de destino de um resgate. O que você faz?', 'Não muda sem confirmar pelo canal oficial; é um sinal clássico de fraude'),
('op-aberta-20', 'operacoes', 20, 'O que é SLA? Como você mediria a qualidade de uma área de operações?', 'Prazo de atendimento combinado; indicadores como erros, prazos cumpridos e retrabalho'),
('op-aberta-21', 'operacoes', 21, 'Onde são liquidados os títulos públicos e onde são liquidadas as ações no Brasil?', 'Títulos públicos no sistema Selic, do Banco Central; ações na câmara da B3'),
('op-aberta-22', 'operacoes', 22, 'Conte um erro que você cometeu e como corrigiu.', 'Assume o erro, age rápido, comunica e muda o processo'),
('op-aberta-23', 'operacoes', 23, 'Como você mantém a atenção a detalhe numa rotina repetitiva?', 'Checklists, conferência cruzada, pausas e automação do que é mecânico'),
('op-aberta-24', 'operacoes', 24, 'Como você explicaria um incidente para um cliente?', 'Transparência, fatos, impacto, o que foi feito e o que muda para não repetir'),
('op-aberta-25', 'operacoes', 25, 'Por que operações? Onde você se vê em cinco anos?', 'Gosto por processos e controle; consciência de que a área abre portas para risco, produtos e gestão')
